use std::collections::HashMap;
use std::io::Write;
use std::net::TcpStream;
use std::sync::Mutex;
use once_cell::sync::Lazy;

static AUDIT_LOG: Lazy<Mutex<Vec<String>>> = Lazy::new(|| Mutex::new(Vec::new()));

#[derive(Debug, Clone)]
pub struct FileProcessingRequest {
    pub filename: String,
    pub submitter_email: String,
    pub department: String,
    pub priority: u8,
}

#[derive(Debug, Clone)]
pub struct EmailNotification {
    pub to: String,
    pub subject: String,
    pub body: String,
    pub headers: HashMap<String, String>,
}

pub fn sanitize_header_value(input: &str) -> String {
    input.chars()
        .filter(|c| *c != '\r' && *c != '\n')
        .collect()
}

pub fn encode_rfc2047(input: &str) -> String {
    if input.is_ascii() && !input.contains(|c: char| c.is_control()) {
        return input.to_string();
    }
    let encoded = base64::encode(input.as_bytes());
    format!("=?UTF-8?B?{}?=", encoded)
}

fn build_audit_trail(req: &FileProcessingRequest) -> String {
    format!(
        "[AUDIT] file={} submitter={} dept={} priority={}",
        req.filename, req.submitter_email, req.department, req.priority
    )
}

fn validate_email_address(email: &str) -> bool {
    let parts: Vec<&str> = email.splitn(2, '@').collect();
    if parts.len() != 2 { return false; }
    let local = parts[0];
    let domain = parts[1];
    if local.is_empty() || domain.is_empty() { return false; }
    if !domain.contains('.') { return false; }
    if domain.starts_with('.') || domain.ends_with('.') { return false; }
    true
}

pub fn compose_notification(req: &FileProcessingRequest) -> Result<EmailNotification, String> {
    if !validate_email_address(&req.submitter_email) {
        return Err("Invalid submitter email".to_string());
    }

    let audit_entry = build_audit_trail(req);
    AUDIT_LOG.lock().unwrap().push(audit_entry);

    let safe_filename = sanitize_header_value(&req.filename);
    let safe_department = sanitize_header_value(&req.department);

    let mut headers = HashMap::new();
    headers.insert("X-File-Name".to_string(), encode_rfc2047(&safe_filename));
    headers.insert("X-Department".to_string(), encode_rfc2047(&safe_department));
    headers.insert("X-Priority".to_string(), req.priority.to_string());
    headers.insert("X-Submitter".to_string(), req.submitter_email.clone());

    let subject = format!("File Processing Complete: {}", safe_filename);
    let body = format!(
        "Your file '{}' has been processed successfully.\n\nDepartment: {}\nPriority: {}",
        req.filename, req.department, req.priority
    );

    Ok(EmailNotification {
        to: req.submitter_email.clone(),
        subject,
        body,
        headers,
    })
}

pub fn send_smtp_notification(notif: &EmailNotification, smtp_host: &str) -> Result<(), String> {
    let mut stream = TcpStream::connect(format!("{}:25", smtp_host))
        .map_err(|e| format!("Connection failed: {}", e))?;

    let mut raw_message = String::new();
    raw_message.push_str(&format!("From: fileprocessor@internal.corp\r\n"));
    raw_message.push_str(&format!("To: {}\r\n", notif.to));
    raw_message.push_str(&format!("Subject: {}\r\n", sanitize_header_value(&notif.subject)));

    for (key, value) in &notif.headers {
        raw_message.push_str(&format!("{}: {}\r\n", key, value));
    }

    raw_message.push_str("MIME-Version: 1.0\r\n");
    raw_message.push_str("Content-Type: text/plain; charset=UTF-8\r\n");
    raw_message.push_str("\r\n");
    raw_message.push_str(&notif.body);

    stream.write_all(raw_message.as_bytes())
        .map_err(|e| format!("Send failed: {}", e))?;

    Ok(())
}

pub fn process_file_request(req: FileProcessingRequest, smtp_host: &str) -> Result<(), String> {
    if req.filename.is_empty() {
        return Err("Filename cannot be empty".to_string());
    }
    if req.priority > 5 {
        return Err("Priority must be 0-5".to_string());
    }

    let notification = compose_notification(&req)?;
    send_smtp_notification(&notification, smtp_host)?;

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_sanitize_header_value() {
        assert_eq!(sanitize_header_value("hello\r\nworld"), "helloworld");
        assert_eq!(sanitize_header_value("normal"), "normal");
    }

    #[test]
    fn test_validate_email() {
        assert!(validate_email_address("user@example.com"));
        assert!(!validate_email_address("invalid"));
        assert!(!validate_email_address("@domain.com"));
    }

    #[test]
    fn test_compose_notification() {
        let req = FileProcessingRequest {
            filename: "report.pdf".to_string(),
            submitter_email: "user@example.com".to_string(),
            department: "Engineering".to_string(),
            priority: 3,
        };
        let notif = compose_notification(&req).unwrap();
        assert_eq!(notif.to, "user@example.com");
    }
}
